    const inputref1=useRef();
    const inputref2=useRef();
          const navigate = useNavigate();
    
const login1=(id,password)=>{
    if(id===""|| password===""){
        alert("enter password or id");


    }
    else{
        if(id==="admin" && passwor==="admin@423" ){
navigate('\teacherdashboard');
        }
        else{
alert("wrong message");
        }
    }
}
    return (
        <>
        <div>
            <Navbar/>
           <div>
      <h2>Teacher login</h2><br></br>
      <div class="input">
        <div className='arrange'>
      <label class="my-label">UserName</label><br></br>
      <input type="text" placeholder='Enter UserName' class="my-input"></input></div>
     
     <div className='arrange'> <label className='my-label'ref={inputref1}>Password</label><br></br>
      <input type='text' placeholder='Enter Password' class="my-input" ref={inputref2}></input></div></div>
     <div class="buttondiv"> <button  onClick={login1(inputref1.current.value,inputref2.current.value)}>Login</button></div>
    </div>
    </div>
    </>
    )
}
export default Teacherlogin1;
